contracts/GiveBlock.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract GiveBlock {

    struct Donation {
        address donor;
        uint256 amount;
        uint256 timestamp;
    }

    Donation[] public donations;

    event DonationMade(
        address indexed donor,
        uint256 amount,
        uint256 timestamp
    );

    function donate() public payable {

        require(msg.value > 0, "Donation must be greater than 0");

        donations.push(
            Donation({
                donor: msg.sender,
                amount: msg.value,
                timestamp: block.timestamp
            })
        );

        emit DonationMade(
            msg.sender,
            msg.value,
            block.timestamp
        );
    }

    function getDonations()
        public
        view
        returns (Donation[] memory)
    {
        return donations;
    }

    function getDonationCount()
        public
        view
        returns (uint256)
    {
        return donations.length;
    }
}

